  raw_internal_name: "v5_independent_match_pct_raw_optional",
  v4_coexistence: "keep_v4_distribution_output",
  continuous_similarity_formula: "sim_d = 1 - ABS(u_d - p_ad)",
  continuous_raw_formula: "raw_cont_a = SUM_d(adj_w_d * sim_d)",
  categorical_boosts: "include_authored_rule_values_with_per_question_multiselect_max",
