  anchor_recompute_rule: "use_runtime_adjusted_weights",
  lower_anchor_formula: "raw_min_a = SUM_d(adj_w_d * MIN(p_ad, 1 - p_ad))",
  baseline_anchor_formula: "raw_mean_a = SUM_d(adj_w_d * (0.5 + p_ad - p_ad^2))",
  upper_anchor_formula: "raw_max_a = SUM_d(adj_w_d * 1)",
  raw_total_formula:
    "raw_total_adjusted_a = raw_cont_a + SUM(categorical_boosts_a) + SUM(failed_gate_adjustments_a) - v5_cat_intercept_a",
